import {EDGE_TYPES,EMPTY_ISLANDS} from './world-map.js';
import {SAVE_KEY,PLAYABLE,freshProgress,sanitizeProgress,completeQuest,stamps} from './core.js';
const $=id=>document.getElementById(id),escape=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
let catalog=[],atlas={architects:[]},relationships=[],content,world,selected=4,current=null,route=0,storageOK=true,progress=freshProgress(),toastTimer,lastFocus=null;
try{progress=sanitizeProgress(JSON.parse(localStorage.getItem(SAVE_KEY)||'null'));}catch(e){storageOK=false;}
function toast(s){$('toast').textContent=s;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4500);}
function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(progress));storageOK=true;}catch(e){storageOK=false;}$('save-status').textContent=storageOK?'進度保存在此瀏覽器':'儲存受限，關閉後進度可能遺失';if(!storageOK)toast('瀏覽器無法儲存進度；本次仍可遊玩，請勿清除或關閉頁面。');updateCounter();}
function updateCounter(){$('stamp-count').textContent=`${stamps(progress).length}/${PLAYABLE.length}`;world?.updateLabels(selected,stamps(progress));}
function dataFor(item){return content.islands.find(x=>x.id===item.slug.replace(/^\d+-/,''));}
function showModal(label,html){lastFocus=document.activeElement;$('modal-label').textContent=label;$('modal-content').innerHTML=html;if(!$('modal').open)$('modal').showModal();world?.setPaused(true);$('modal').scrollTop=0;}
function closeModal(){$('modal').close();world?.setPaused(false);if(current)world?.focusControls();else lastFocus?.focus?.();}
function geography(id){return atlas.architects.find(x=>x.id===id);}
function buildingSiteLabel(g){return g?.building?.siteRole==='original'?'作品原址':'建築實址';}
function currentSiteFor(g){return g?.building?.currentSite||g?.currentSite;}
function originalSiteFor(g){return g?.building?.originalSite||g?.originalSite;}
function validCoordinates(site){return Number.isFinite(site?.lat)&&Number.isFinite(site?.lon);}
function coordinateText(site){return validCoordinates(site)?`${site.lat.toFixed(5)}°, ${site.lon.toFixed(5)}°`:'尚未提供可定位座標';}
function enableLandmarkLayer(layer){const button=document.querySelector(`[data-landmark-layer="${layer}"]`);if(button)button.setAttribute('aria-pressed','true');world?.setLandmarkLayer?.(layer,true);}
function focusBuilding(id){enableLandmarkLayer('building');selectIsland(id);world?.mapAction('focus');}
function selectIsland(id,focus=false){
  id=Number(id);if(current||!catalog.some(i=>i.id===id))return;selected=id;
  const item=catalog.find(x=>x.id===id),g=geography(id),d=item.playable?dataFor(item):null,done=stamps(progress).includes(id);
  world?.updateLabels(selected,stamps(progress));
  $('selection').innerHTML=`<div class="cover"><img src="assets/miniatures/${String(id).padStart(2,'0')}.png" alt="${escape(item.title)}的 Q 版建築示意" width="300" height="170"><span class="tag">${done?'已收集島章':item.playable?'開放探索 · 3 個觀察點':'預覽島 · 尚未開放遊戲'}</span><span class="island-no">${String(id).padStart(2,'0')}</span></div><div class="selection-body"><h2 id="selected-title">${escape(item.title)}</h2><p class="architect">${escape(item.architect)}${id===3?' · Truus Schröder 合作':id===5?' · Pierre Jeanneret 合作':''}</p><div class="geo-summary"><p class="building-location"><span>${buildingSiteLabel(g)}</span> ${escape(g?.building.label||'核對中')}</p><p><span>歷史執業</span> ${escape(g?.practiceBase.label||'核對中')}</p></div><button class="geo-details" id="island-geography">建築定位、人物與來源 ↗</button><p class="miniature-motif">${escape(world?.miniatureInfo?.(id))}</p><div class="selection-actions"><button id="focus-miniature" class="focus-miniature">⌕ 聚焦${g?.building.siteRole==='original'?'作品原址':'建築實址'}</button>${item.playable?`<p class="blurb">${escape(d.theme)}。<br>與大師相遇，帶回一枚建築島章。</p><button class="primary" id="enter-island">${done?'再次登島':'登島探索'} <span>↗</span></button>`:`<p class="preview-note">Q 版建築已登場。登島角色與任務尚未開放。</p><a class="text-link" href="${escape(item.url)}" target="_blank" rel="noopener noreferrer">查看獨立導覽 ↗</a>`}</div><div class="map-browse"><button id="previous-island" aria-label="上一座島">← 上一島</button><button id="all-islands">25 座名錄</button><button id="next-island" aria-label="下一座島">下一島 →</button></div></div>`;
  $('island-geography').onclick=()=>showGeography(id);$('focus-miniature').onclick=()=>focusBuilding(id);$('enter-island')?.addEventListener('click',()=>enterIsland(id));$('previous-island').onclick=()=>focusBuilding(id===1?25:id-1);$('next-island').onclick=()=>focusBuilding(id===25?1:id+1);$('all-islands').onclick=showDirectory;
  if(focus===true){enableLandmarkLayer('building');world?.mapAction('focus');}
}
function buildingIndexMarkup(ids){return ids.map(id=>{const item=catalog.find(i=>i.id===Number(id)),g=geography(Number(id));return item?`<button class="quest-row ${item.id===selected?'is-selected':''}" data-select="${item.id}"><span class="quest-dot">${String(item.id).padStart(2,'0')}</span><span>${escape(item.title)}<small>${escape(g?.building.label)} · ${item.playable?'可探索':'預覽'}${g?.building.siteRole==='original'?' · 歷史原址':''}</small><small>${escape(item.architect)}</small></span></button>`:'';}).join('');}
function bindBuildingChoices(){for(const button of $('modal-content').querySelectorAll('[data-select]'))button.onclick=()=>{const id=Number(button.dataset.select);closeModal();if(current)backMap();focusBuilding(id);};}
function showDirectory(){showModal('ARCHIPELAGO INDEX / 建築實址名錄',`<h2 id="modal-title">25 件作品，各自回到所在之地。</h2><p>建築島依作品座標定位，不隨建築師的國籍或執業基地移動。25 座原始建築模型皆可登島，完成 75 個觀察任務，收藏 25 枚島章。</p>${regionalCountMarkup()}<div class="island-index">${buildingIndexMarkup(catalog.map(i=>i.id))}</div><p class="tiny">點選作品會轉向它的實址或有明確標示的歷史原址。同一格內的作品透過名單切換，地理定位點不移位。原有 25 個獨立導覽連結保持不變；共同設計者與來源見各作品資料卡。</p>`);bindBuildingChoices();}
async function enterIsland(id){const item=catalog.find(x=>x.id===id);if(!item?.playable){toast('這座島尚未完成載入，請稍後重試。');return;}const ticket=++route;current=item;$('main').dataset.view='island';const d=dataFor(item),firstVisit=!progress.visited.includes(id);$('map-intro').hidden=true;$('map-toolbar').hidden=true;$('atlas-toolbar').hidden=true;$('selection').hidden=true;$('sea-title').hidden=true;$('island-hud').hidden=false;$('island-controls').hidden=false;$('loading').hidden=false;$('load-title').textContent=`航向${d.name}`;$('load-text').textContent=`準備${item.title}的原始模型。一次只載入目前這座島。`;$('load-progress').removeAttribute('value');$('load-progress').hidden=false;$('load-error-actions').hidden=true;$('loading').querySelector('.spinner').hidden=false;$('island-kicker').textContent=`ISLAND ${String(id).padStart(2,'0')} / ${d.name}`;$('island-title').textContent=item.title;$('island-author').textContent=d.architect+(id===3?' × Truus Schröder':id===5?' × Pierre Jeanneret':'');$('island-original-link').href=item.originalModelUrl||item.url;$('photo-original-link').href=item.originalModelUrl||item.url;$('island-original-link').title=`在新分頁開啟${item.title}原作品模型，保留目前遊戲`;setLightingUI(null);$('interaction').hidden=false;nearChanged(null);world.setPaused(true);renderObjectives();try{const result=await world.enter(item,(pct,bytes)=>{if(ticket!==route)return;if(pct!=null)$('load-progress').value=pct;if(bytes)$('load-text').textContent=`正在載入原始模型 · ${(bytes/1048576).toFixed(1)} MB`;});if(ticket!==route||result.cancelled)return;$('loading').hidden=true;world.setPaused(false);world.setCompleted(progress.quests[id]||[]);setLightingUI(result);await world.setTimeOfDay?.(progress.settings.timeOfDay);if(ticket!==route)return;$('time-of-day').value=world.timeOfDay||progress.settings.timeOfDay;for(const control of ['rotate-left','rotate-right','zoom-in','zoom-out','reset-camera']){$(control).disabled=Boolean(result.fallback);$(control).title=result.fallback?'2D 相容模式不使用即時 3D 鏡頭':'';}$('movement-hint').textContent=result.fallback?'無 WebGL2：2D 縮圖探索，無即時 3D 行走視角':'拖曳轉視角 · WASD 移動 · 點地面前往';world.focusControls();if(!progress.visited.includes(id))progress.visited.push(id);save();$('renderer-status').textContent=result.fallback?'2D 相容探索 · 非即時 3D':'WebGL2 · 即時 3D · 眼高自由行走';if(result.fallback)toast('此瀏覽器未提供 WebGL2，已切換 2D 相容探索，非即時 3D。');if(firstVisit&&progress.visited.length===1)showTutorial(true);else toast('歡迎回來。靠近大師或選擇左方觀察任務。');}catch(e){if(ticket!==route)return;world.setPaused(true);$('loading').querySelector('.spinner').hidden=true;$('load-title').textContent='這次還沒抵達';$('load-text').textContent='模型載入未完成。可能是網路中斷或裝置資源不足；可重試，或返回地球。你的已存進度不會清除。';$('load-progress').hidden=true;$('load-error-actions').hidden=false;console.error('Island loading failed',e);}}
function setLightingUI(result){const select=$('time-of-day');select.disabled=!result||Boolean(result.fallback);$('lights-enabled').disabled=select.disabled||!result.lighting?.artificialLightingAvailable;$('lights-enabled').checked=true;$('lighting-note').textContent=!result?'材質與光影準備中':result.fallback?'無 WebGL2：光影切換需即時 3D':result.lighting?.artificialLightingAvailable?'原作材質；夜間燈具依來源近似，非精確復原':'夜間環境可用；人工燈證據不足，維持關閉';}
function backMap(){++route;current=null;$('main').dataset.view='map';world.setPaused(false);world.showMap();$('loading').hidden=true;$('island-hud').hidden=true;$('island-controls').hidden=true;$('map-intro').hidden=false;$('map-toolbar').hidden=false;$('atlas-toolbar').hidden=false;$('selection').hidden=false;$('sea-title').hidden=false;selectIsland(selected);}
function renderObjectives(){if(!current)return;const id=current.id,d=dataFor(current),done=progress.quests[id]||[];$('task-count').textContent=`${done.length}/3`;$('objectives').innerHTML=`<button class="quest-row npc ${progress.met.includes(id)?'done':''}" data-guide="npc"><span class="quest-dot">${progress.met.includes(id)?'✓':'師'}</span><span>與${d.npc.name.split('｜')[0]}相遇<small>教學角色 · 靠近後對談</small></span></button>${d.quests.map((q,i)=>`<button class="quest-row ${done.includes(i)?'done':''}" data-guide="${i}"><span class="quest-dot">${done.includes(i)?'✓':i+1}</span><span>${escape(q.title)}<small>${done.includes(i)?'已完成 · 可再次觀察':'點此沿步道前往'}</small></span></button>`).join('')}<button class="quest-row" id="island-about"><span class="quest-dot">i</span><span>作品資料與來源<small>模型限制 · 既有導覽</small></span></button>`;for(const b of $('objectives').querySelectorAll('[data-guide]'))b.onclick=()=>{const n=b.dataset.guide;if(n==='npc')world.guide('npc');else world.guide('quest',+n);toast('沿步道前往。抵達後按下互動按鈕。');if(innerWidth<=700){$('objectives').hidden=true;$('objectives-toggle').setAttribute('aria-expanded','false');}};$('island-about').onclick=showAbout;world?.setCompleted(done);updateCounter();}
function nearChanged(n){const b=$('interact-btn');b.disabled=!n;b.textContent=!n?'走近大師或觀察點':n.kind==='npc'?'與大師對談 · Space':`觀察 ${n.index+1} · Space`;if(innerWidth<=700&&n)b.textContent=n.kind==='npc'?'與大師對談':`開啟觀察 ${n.index+1}`;}
function photoChanged(shot){
 $('photo-info').hidden=!shot;$('photo-info').classList.toggle('is-fallback',Boolean(shot?.fallback));$('main').classList.toggle('photo-mode',Boolean(shot));
 if(!shot){$('movement-hint').textContent=world?.gpu?'拖曳轉視角 · WASD 移動 · 點地面前往':'無 WebGL2：2D 縮圖探索，無即時 3D 行走視角';return;}
 $('photo-kicker').textContent=shot.returning?'RETURNING / 返回俯視':shot.transitioning?'ENTERING / 進入眼高視角':`LIVE 3D / 觀察區 ${shot.index+1}`;
 $('photo-title').textContent=shot.label;
 $('photo-note').textContent=shot.kind==='interior'?'角色與視角同步在室內地板行走。走入金色返回圈，回到原入口與俯視。進出使用短淡場，非連續穿越樓梯。':`同一 3D 場景，眼高 1.60 m。可在金色界線內自由行走，走出約 ${(shot.walkRadius/shot.scale).toFixed(1)} m 範圍即返回俯視。`;
 $('movement-hint').textContent=shot.transitioning?'同一場景轉換中…':'WASD／方向鈕前後左右走 · 拖曳自由看';
 $('photo-free').hidden=true;$('photo-leave').disabled=Boolean(shot.returning);$('photo-leave').textContent='返回俯視 · Esc';
}
function interact(){if(!current||!world.nearest||$('loading').hidden===false)return;const n=world.nearest;if(n.kind==='npc')showNPC();else showQuest(n.index);}
function award(id){return stamps(progress).includes(id);}
function showNPC(){const d=dataFor(current),id=current.id;showModal('MEET THE MASTER / 大師的教學化身',`<h2 id="modal-title">${escape(d.npc.name)}</h2><p class="tiny">${escape(d.npc.label)}。造型為風格化角色，不是史實肖像復原。</p><p>${escape(d.npc.dialogue)}</p><div class="concept-card"><p class="eyebrow">這趟旅程的線索</p><h3>${escape(d.theme)}</h3><p>${d.quests.map((q,i)=>`${i+1}. ${escape(q.title)}`).join('<br>')}</p></div><p class="tiny">${escape(d.credit)}</p><button class="primary" id="accept-quests">${progress.met.includes(id)?'繼續我的探索':'接下觀察任務'} ↗</button>`);$('accept-quests').onclick=()=>{const was=award(id);if(!progress.met.includes(id))progress.met.push(id);save();renderObjectives();if(!was&&award(id))showAward();else{closeModal();toast('先觀察，再回答。三個線索會拼成一張概念卡。');}};}
function showQuest(index){const d=dataFor(current),q=d.quests[index],id=current.id,already=(progress.quests[id]||[]).includes(index);world.focusPoint(index);showModal(`OBSERVATION ${index+1} / ${q.locationLabel}`,`<h2 id="modal-title">${escape(q.title)}</h2><p>${q.observation.map(escape).join('<br>')}</p><p class="tiny">${world.gpu?'抵達觀察區自動從同一場景切換眼高視角，關閉視窗後可用 WASD／方向鈕前後左右行走、拖曳上下左右觀看。室外走出金色範圍、室內走入金色返回圈，都會恢復原先俯視鏡頭；Esc 可直接返回。室內進出以短淡場移到實際樓板，不代表沿樓梯連續通行。':'此瀏覽器沒有 WebGL2。目前只有 2D 縮圖探索，不能呈現即時 3D 眼高行走；縮圖不是第一人稱畫面。任務問答與原有探索進度仍可使用。'}</p><h3 class="question">${escape(q.question)}</h3><div id="answers">${q.choices.map((answer,i)=>`<button class="answer" data-answer="${i}">${String.fromCharCode(65+i)}　${escape(answer)}</button>`).join('')}</div><div id="answer-feedback" role="status" aria-live="polite"></div>${already?'<p class="tiny">這個任務已完成，可以再次練習，不會重複計數。</p>':''}`);for(const b of $('answers').children)b.onclick=()=>{const choice=+b.dataset.answer;if(choice!==q.correctIndex){b.classList.add('wrong');$('answer-feedback').innerHTML=`<div class="explanation">${escape(content.feedback.incorrect)}</div>`;return;}for(const btn of $('answers').children)btn.disabled=true;b.classList.add('correct');const before=award(id);completeQuest(progress,id,index);save();renderObjectives();const newStamp=!before&&award(id);$('answer-feedback').innerHTML=`<div class="explanation"><strong>${escape(content.feedback.correct)}</strong><br>${escape(q.explanation)}</div><button class="primary" id="quest-done">${newStamp?'領取島章與概念卡':'繼續探索'} ↗</button>`;$('quest-done').onclick=()=>{if(newStamp)showAward();else{closeModal();if((progress.quests[id]||[]).length===3&&!progress.met.includes(id))toast('觀察已完成！再與大師對談，就能收集島章。');}};};}
function showAward(){const d=dataFor(current),all=stamps(progress).length===PLAYABLE.length;showModal('PASSPORT STAMP / 新的島章',`<div class="stamp collected" style="width:120px;margin:0 auto 18px"><b>${String(current.id).padStart(2,'0')}</b><span>${escape(d.name)}</span><small>ARCHITECTURE ARCHIPELAGO</small></div><h2 id="modal-title">${all?'群島觀察家，歡迎你。':'把這個想法，帶回海上。'}</h2><p>${all?'25 枚島章已收集完成。你走遍 25 座探索島，完成 75 個建築觀察任務。':'完成大師對談與三個觀察任務，這枚島章已收入你的護照。'}</p>${conceptMarkup(d)}<div class="modal-actions"><button class="primary" id="award-map">返回群島地圖</button><button id="award-stay">再逛一會兒</button></div>`);$('award-map').onclick=()=>{closeModal();backMap();};$('award-stay').onclick=closeModal;}
function conceptMarkup(d){return `<article class="concept-card"><p class="eyebrow">CONCEPT CARD / ${escape(d.name)}</p><h3>${escape(d.conceptCard.title)}</h3><p>${escape(d.conceptCard.summary)}</p><p class="tiny">${d.conceptCard.keywords.map(escape).join(' · ')}</p><p class="tiny">帶走一個問題：${escape(d.conceptCard.reflection)}</p></article>`;}
function showPassport(){const collected=stamps(progress);showModal('MY FIELD NOTES / 建築觀察護照',`<div class="passport-cover"><h2 id="modal-title">我的建築護照</h2><span>${collected.length}<small style="font-size:16px">/${PLAYABLE.length}</small></span></div><div class="stamp-grid">${PLAYABLE.map(id=>{const d=dataFor(catalog.find(i=>i.id===id));return `<div class="stamp ${collected.includes(id)?'collected':''}"><b>${String(id).padStart(2,'0')}</b><span>${escape(d.name)}</span><small>${collected.includes(id)?'已收集':`${progress.quests[id]?.length||0}/3 個觀察`}</small></div>`;}).join('')}</div><p>${collected.length===PLAYABLE.length?'25 座群島探索完成。你已收藏 25 張建築概念卡。':'每島完成一次大師對談與三個觀察任務，即可解鎖島章與概念卡。'}</p>${PLAYABLE.map(id=>{const d=dataFor(catalog.find(i=>i.id===id));return collected.includes(id)?conceptMarkup(d):`<article class="concept-card locked"><p class="eyebrow">尚待探索 / ${escape(d.name)}</p><h3>${escape(d.conceptCard.title)}</h3><p class="tiny">完成本島探索後解鎖。</p></article>`;}).join('')}<p class="tiny">進度僅保存在這個瀏覽器，不會跨裝置同步。清除網站資料或使用私密瀏覽，可能遺失進度。</p><div class="modal-actions"><button id="reset-progress" class="danger">重設本遊戲進度</button><button id="passport-close">繼續探索</button></div>`);$('reset-progress').onclick=confirmReset;$('passport-close').onclick=closeModal;}
function confirmReset(){showModal('RESET PASSPORT / 確認重設',`<h2 id="modal-title">清空這本護照？</h2><p>會清除本遊戲在此瀏覽器儲存的 25 島任務、對談與島章。這無法復原，不影響原有 25 個建築導覽網站。</p><div class="modal-actions"><button id="cancel-reset">保留進度</button><button id="confirm-reset" class="danger">確定清除遊戲進度</button></div>`);$('cancel-reset').onclick=showPassport;$('confirm-reset').onclick=()=>{const settings={...progress.settings};progress=freshProgress();progress.settings=settings;save();if(current)renderObjectives();showPassport();toast('本遊戲進度已重設。原有導覽網站沒有變更。');};}
function showTutorial(onIsland=false){showModal('HOW TO EXPLORE / 地球探索指南',`<h2 id="modal-title">轉動世界，慢慢觀察。</h2><p>這是一場不計時的建築探索。地球收錄 25 座大師建築：25 座皆可登島，以原始材質模型與有來源的光影設定探索。</p><div class="tutorial-steps"><div class="tutorial-step"><b>1</b><span><strong>選建築，與大師相遇</strong>轉動地球或從名錄選擇建築。登島後點「與大師相遇」，沿室外步道前往，抵達後按互動鍵對談。</span></div><div class="tutorial-step"><b>2</b><span><strong>從三個線索讀懂建築</strong>點地面行走，或點任務自動帶路。支援 WebGL2 時，抵達觀察區切到同一 3D 場景的眼高視角，WASD／方向鈕自由走、拖曳自由看；室外走出範圍、室內走進返回圈後恢復原鏡頭。再按互動、回答問題，答錯可以再試。</span></div><div class="tutorial-step"><b>3</b><span><strong>在護照裡留下一個想法</strong>完成對談與三題，即可收集島章與概念卡。進度自動儲存在目前瀏覽器。</span></div></div><h3>六角地球怎麼讀？</h3><p>地塊以六角格為主，並以 12 個五角格閉合球面。25 件建築依各自實址定位；已遷移或臨時作品明示歷史原址，有可靠現址時另設次要標記。格網與海岸是風格化底圖，不會把建築移到格心。同格作品以名單切換縮景，定位點保持不動。另有獨立的「歷史執業地標」，以人物插畫或有來源的肖像呈現，不表示國籍、出生地或現居地。</p><h3>關係與交通，分開閱讀</h3><p>授業、共事是有來源的歷史關係；理念虛線是策展對讀。青色線另外連接跨國的歷史執業地標與本次入選作品，僅為地理關聯，不增加史料關係。道路、船舶航線、飛行弧線是風格化交通示意，不是實際歷史行程，不能跨地塊行走，也不是旅行模擬。可在「地理圖層」分別切換建築、人物、青色線與已核實現址。</p><h3>轉動與聚焦</h3><p>滑鼠拖曳轉動地球、滾輪縮放；手機單指旋轉、雙指捏合縮放。區域按鈕會轉向北美、歐洲、日本或臺灣，數字只計本次入選建築；選建築後按「聚焦建築實址」或「聚焦作品原址」近看，按「重設全景」返回全球。</p><p class="tiny">鍵盤：先點地球，方向鍵旋轉，＋／− 縮放，F 聚焦、0 重設。這是球面旋轉，不提供平移。Q 版建築只提取特徵，不代表實際尺寸。無 WebGL2 時使用軟體 2D 球面投影與預先繪製的建築圖像，會明確標示「非即時 3D」。</p><h3>登島後，自由看、自在走</h3><p>先點場景。滑鼠按住拖曳可左右轉向、上下調整俯仰；滾輪拉近或拉遠。輕點地面仍會沿步道前往，拖曳放開不會誤觸行走。</p><p><span class="key">W / S</span> 依鏡頭方向前進／後退　<span class="key">A / D</span> 左右橫移。方向鍵也能行走，放開即停；手動移動會取消自動帶路。</p><p><span class="key">Q / E</span> 轉向　<span class="key">[ / ]</span> 俯仰　<span class="key">＋ / −</span> 縮放　<span class="key">R</span> 重設鏡頭　<span class="key">Space</span> 靠近後互動。</p><p class="tiny">手機：單指拖曳轉視角、雙指捏合縮放；輕點地面或按住右下方向鍵行走。左下「重設鏡頭」可回到全景。可收合任務清單，讓場景更開闊。對話與選單開啟時暫停操作。</p><p class="tiny">若裝置不支援 WebGL2，2D 相容模式仍可點選或用 WASD／方向鍵行走，但不提供 3D 轉向、俯仰與縮放。</p><p class="tiny">一般俯視探索仍走室外路線。16 個室內觀察區可在經模型幾何檢查的實際地板上行走，玻璃、牆面與家具不可穿越，金色返回圈帶回原入口。進出室內使用短淡場，不宣稱整棟、樓梯或坡道都能連續通行。NPC 全為教學改寫，非本人原話。探索島嶼、植栽與步道是遊戲場景，不是原址復原。</p><button id="tutorial-done" class="primary">${onIsland?'開始我的探索':'回到地球'} ↗</button>`);$('tutorial-done').onclick=()=>{closeModal();if(onIsland)toast('先與大師相遇吧。點任務清單可以自動帶路。');};}
function showAbout(){if(!current)return;const d=dataFor(current),sources=content.sources.filter(s=>d.quests.some(q=>q.sourceIds.includes(s.id)));showModal('BUILDING DOSSIER / 作品資料',`<img class="modal-image" src="${current.poster}" alt="${escape(current.title)}原模型外觀"><h2 id="modal-title">${escape(current.title)}</h2><p>${escape(d.buildingEnglish)}<br>${escape(d.year)} · ${escape(d.location)}<br>${escape(d.architect)}<br>${escape(d.credit)}</p><a class="tour-link" href="${escape(current.originalModelUrl||current.url)}" target="_blank" rel="noopener noreferrer">開啟原作品模型網站 ↗</a><h3>模型、材質與光影</h3><p class="tiny">使用原作品網站同一份 GLB、原始材質配置與材質貼圖，依島嶼比例呈現。日間與黃昏保留原來源 HDR 環境與太陽光設定；夜間沿用原作品網站的來源參考與教學照明設定；各作的證據強度不同，可能參考後期修復或僅為原模型的夜景假設。形態、位置、光度與色溫均非精確復原。沒有硬體光線追蹤或完整間接光反彈。</p><p class="tiny">${current.artificialLightingAvailable?'夜間室內燈可開關，省電畫質減少同時作用光源與陰影。':'本作品缺乏足夠人工照明證據：可切換夜間環境，人工燈維持關閉。'}</p><h3>本作品的照明依據與限制</h3><p class="tiny">${escape(current.lightingSummary||'原來源中的三臂落地燈與廚房檯下螢光燈，位置與光度為教學估算。')}</p>${(current.lightingNotes||[]).length?`<details><summary>原模型照明註記（遊戲另縮減即時光源預算）</summary><ul>${current.lightingNotes.map(note=>`<li class="tiny">${escape(note)}</li>`).join('')}</ul></details>`:''}<h3>可行走範圍與史實界線</h3><p class="tiny">${escape(current.navigationNote||'室內只開放經模型地坪與淨空檢查的限定觀察區，並非全棟自由穿行。')} 室內進出採短淡場與金色返回圈，不代表真實樓梯或門的連續通行。</p><p class="tiny">島嶼與步道是遊戲設計，不代表原址；原址的大面積草地、遠景樹木與引道隱藏。${escape(current.landscapeNote||'')} 原模型是教學重建，不等於測繪、施工或完整歷史復原。<br>${escape(current.uncertainty)}</p><h3>任務參考來源</h3>${sourceLinks(sources)}<details><summary>原模型與材質來源</summary>${sourceLinks(current.sources)}</details><details><summary>照明史料與推估依據</summary>${sourceLinks(current.lightingSources)}</details><h3>繼續閱讀</h3><a class="text-link" href="${escape(current.originalFallbackUrl||current.url)}" target="_blank" rel="noopener noreferrer">原作品穩定版導覽與概念動畫 ↗</a><p class="tiny">另開分頁，保留目前探索。影片由你自行播放，遊戲不會自動下載或播放所有影片。</p>`);}
function webUrl(value){try{const url=new URL(String(value));return ['https:','http:'].includes(url.protocol)?url.href:'';}catch{return '';}}
function sourceLinks(sources=[]){const items=(Array.isArray(sources)?sources:[]).map(source=>{const url=webUrl(typeof source==='string'?source:source?.url);if(!url)return '';const title=typeof source==='string'?new URL(url).hostname:source.title||source.label||new URL(url).hostname;return `<li><a href="${escape(url)}" target="_blank" rel="noopener noreferrer">${escape(title)} ↗</a>${source?.supports?`<small>${escape(source.supports)}</small>`:''}</li>`;}).join('');return items?`<ul class="source-list">${items}</ul>`:'';}
const REGION_GROUPS=[{key:'america',label:'北美',test:b=>['north-america','america'].includes(b.region)},{key:'europe',label:'歐洲',test:b=>b.region==='europe'},{key:'japan',label:'日本',test:b=>b.countryCode==='JP'},{key:'taiwan',label:'臺灣',test:b=>b.countryCode==='TW'}];
function regionalCounts(){return REGION_GROUPS.map(group=>({...group,count:atlas.architects.filter(g=>group.test(g.building||{})).length}));}
function regionalCountMarkup(){const groups=regionalCounts(),other=atlas.architects.length-groups.reduce((sum,g)=>sum+g.count,0);return `<div class="regional-counts" aria-label="依作品主定位計算的入選建築數">${groups.map(g=>`<span>${g.label}<b>${g.count}</b>件</span>`).join('')}${other>0?`<span>其他區域<b>${other}</b>件</span>`:''}</div><p class="tiny count-note">僅計這 25 件作品的主定位，不計人物地標或重複計算遷移後現址。</p>`;}
function updateRegionalCounts(){for(const group of regionalCounts()){const button=document.querySelector(`[data-map-action="region-${group.key}"]`);if(button){button.textContent=`${group.label} ${group.count}`;button.setAttribute('aria-label',`聚焦${group.label}，本次入選建築 ${group.count} 件`);button.title='數字為作品主定位數，非建築師人數';}}}
function coordinateNote(site){const precision=site?.coordinatePrecision,labels={approximate_building_site:'建築場址約略座標',approximate_site:'建築場址約略座標',approximate_historical_site:'歷史原址約略座標',approximate_city_anchor:'歷史執業城市的約略座標',verified_building_site:'經來源核對的建築場址座標',building_site:'建築場址座標',exact_building_site:'建築場址座標',historical_site:'歷史原址座標'};return [labels[precision]||'來源核對的場址定位，非測繪資料',site?.coordinateNote].filter(Boolean).map(s=>escape(String(s).replace(/。+$/,''))).join('。');}
function siteStatusText(site){const status=site?.siteStatus;if(!status)return '';const labels={extant:'建築仍位於此址',in_situ:'建築仍位於原址',relocated:'建築已遷移，這裡標示歷史原址',temporary:'臨時建築的歷史展出地點',demolished:'建築已拆除，這裡標示歷史原址',historical:'歷史原址，不代表現存於此'};return escape(labels[status]||status);}
function showGeography(id){
  const item=catalog.find(i=>i.id===Number(id)),g=geography(Number(id));if(!g||!item)return;
  const placement=world?.globe?.placements?.get(g.id),site=g.building,currentSite=currentSiteFor(g),originalSite=originalSiteFor(g),clusterIds=world?.globe?.buildingClusters?.get(placement?.tileId)||[],gridDistance=placement?.cellDistanceKm;
  const association=g.practiceBase.countryCode&&site.countryCode&&g.practiceBase.countryCode!==site.countryCode;
  showModal('BUILDING GEOGRAPHY / 建築實址與歷史',`<img class="miniature-enlarged" src="assets/miniatures/${String(g.id).padStart(2,'0')}.png" alt="${escape(item.title)} Q 版建築示意"><h2 id="modal-title">${escape(item.title)}</h2><p class="dossier-author">${escape(item.architect)}</p><div class="geo-dossier"><section class="site-primary"><span class="location-badge">主定位 · ${buildingSiteLabel(g)}</span><h3>${escape(site.label)}</h3><p>${escape(site.note||'')}</p>${siteStatusText(site)?`<p class="site-status">${siteStatusText(site)}</p>`:''}<p class="tiny">地圖定位：${coordinateText(site)}<br>${coordinateNote(site)}。建築定位點固定在這組座標，不以人物執業地或格網中心替代。</p>${Number.isFinite(gridDistance)?`<p class="tiny">最近格心距離約 ${Math.round(gridDistance)} 公里，這是底圖網格的解析度差距，不是建築定位點的位移。</p>`:''}${sourceLinks(site.sources)}</section>${currentSite&&currentSite!==site?`<section class="site-secondary"><span class="location-badge secondary">次要標記 · 已核實現址</span><h3>${escape(currentSite.label)}</h3><p>${escape(currentSite.note||'')}</p><p class="tiny">${coordinateText(currentSite)}${currentSite.coordinateNote?`<br>${escape(currentSite.coordinateNote)}`:''}。保留原作的歷史定位，現址不另占 25 件典藏名額。</p>${currentSite.caveats?.length?`<p class="tiny">${escape(currentSite.caveats.join('；'))}</p>`:''}${sourceLinks(currentSite.sources)}${validCoordinates(currentSite)?`<button class="geo-details" id="geo-current">聚焦已核實現址 ↗</button>`:''}</section>`:''}${originalSite&&site.siteRole!=='original'?`<section class="site-secondary"><span class="location-badge secondary">歷史補充 · 原址</span><h3>${escape(originalSite.label)}</h3><p>${escape(originalSite.note||'')}</p><p class="tiny">${coordinateText(originalSite)}</p>${sourceLinks(originalSite.sources)}</section>`:''}${site.credits?.length?`<h3>共同設計與參與</h3><p>${escape(Array.isArray(site.credits)?site.credits.join('；'):site.credits)}</p>`:''}<h3>歷史執業地標 · ${escape(g.practiceBase.label)}</h3><p>${escape(g.practiceBase.note||'以具有來源的歷史專業活動地點作人物地標。')}</p><p class="tiny">此為生涯中代表性的執業據點，不表示國籍、出生地或現居地。它與上方建築實址分開呈現。</p><button class="geo-details" id="geo-master">查看人物卡與歷史來源 ↗</button>${association?'<button class="geo-details geography-link" id="geo-association">青色跨國地理關聯 ↗</button>':''}${clusterIds.length>1?`<div class="cluster-explainer"><strong>同一格內有 ${clusterIds.length} 件入選作品</strong><p>同格不等於同址。縮景依選取切換，各作品的定位點仍固定在原座標。</p><button class="geo-details" id="geo-cluster">切換同格作品 ↗</button></div>`:''}</div><p class="tiny">${escape(world?.miniatureInfo?.(g.id)||'')}。Q 版是特徵示意，並非精確比例復原。${g.caveats?.length?escape(g.caveats.join('；')):''}</p><div class="modal-actions"><button id="geo-connections">本作品的關係線</button><button id="geo-focus" class="primary">聚焦${site.siteRole==='original'?'作品原址':'建築實址'}</button></div>`);
  $('geo-focus').onclick=()=>{closeModal();if(current)backMap();focusBuilding(g.id);};$('geo-connections').onclick=()=>showNetwork(g.id);$('geo-master').onclick=()=>showMasterFor(g.id);$('geo-association')?.addEventListener('click',()=>showGeographicAssociation(g.id));$('geo-cluster')?.addEventListener('click',()=>showBuildingCluster(placement.tileId));$('geo-current')?.addEventListener('click',()=>{closeModal();if(current)backMap();enableLandmarkLayer('history');world?.focusCurrentSite?.(g.id);});
}
function figureIllustration(g){const colors=['#37585f','#715e70','#8c6851','#486c61','#526180'],color=colors[(g.id-1)%colors.length],pair=/SANAA|妹島/.test(g.architect);const person=(x,scale=1)=>`<g transform="translate(${x} 0) scale(${scale})"><ellipse cx="55" cy="126" rx="31" ry="7" fill="#486050" opacity=".15"/><path d="M32 121V84Q33 68 55 68Q77 68 78 84V121" fill="${color}"/><path d="M48 71L55 88L62 71" fill="#e9e1cc"/><path d="M48 119V135M64 119V135" stroke="#344740" stroke-width="10" stroke-linecap="round"/><rect x="27" y="90" width="31" height="22" rx="2" transform="rotate(-8 27 90)" fill="#e9d3a4"/><path d="M33 96L46 95M34 101L47 100" stroke="#927c56" stroke-width="1.5"/><circle cx="55" cy="45" r="25" fill="#d9b991"/><path d="M30 45Q28 14 54 17Q83 14 80 45L72 31L51 34L34 30Z" fill="#ddd8c8"/><path d="M35 43H49V52H35ZM60 43H74V52H60ZM49 46H60" fill="none" stroke="#304c48" stroke-width="2"/><path d="M51 59Q56 62 61 58" fill="none" stroke="#82634f" stroke-width="1.4"/></g>`;return `<figure class="master-visual illustration"><svg viewBox="0 0 160 150" role="img" aria-label="${escape(g.architect)}的風格化人物插畫，非史實肖像復原"><circle cx="80" cy="70" r="61" fill="#e8eadb"/>${pair?person(8,.76)+person(71,.76):person(25)}</svg><figcaption>人物插畫 · 非史實肖像復原</figcaption></figure>`;}
function portraitMarkup(g){const p=g.portrait;if(!p?.path||!webUrl(p.filePage)||!p.license||!webUrl(p.licenseUrl)||!p.creator)return figureIllustration(g);return `<figure class="master-visual portrait"><img src="${escape(p.path)}" alt="${escape(g.architect)}的有來源照片" loading="lazy"><figcaption>${escape(p.attribution||p.creator)}<br><a href="${escape(webUrl(p.filePage))}" target="_blank" rel="noopener noreferrer">原始照片與作者</a> · <a href="${escape(webUrl(p.licenseUrl))}" target="_blank" rel="noopener noreferrer">${escape(p.license)}</a></figcaption></figure>`;}
function masterCardMarkup(g){const item=catalog.find(i=>i.id===g.id);return `<article class="master-card">${portraitMarkup(g)}<div class="master-card-body"><p class="eyebrow">HISTORICAL PRACTICE / 歷史人物地標</p><h3>${escape(g.architect)}</h3><p><strong>代表執業據點</strong><br>${escape(g.practiceBase.label)}</p><p>${escape(g.practiceBase.note||'')}</p><p class="tiny">${coordinateText(g.practiceBase)} · 城市／據點近似定位，非現居地址。</p>${sourceLinks(g.practiceBase.sources)}${g.nationality?.label?`<div class="nationality-note"><strong>國籍／身分資料（與定位分開）</strong><p>${escape(g.nationality.label)}${g.nationality.note?`<br>${escape(g.nationality.note)}`:''}</p>${sourceLinks(g.nationality.sources)}</div>`:''}${g.alternateBases?.length?`<p class="tiny">其他生涯／執業基地：${g.alternateBases.map(base=>`${escape(base.country||'')}・${escape(base.city||base.label||'')}（${escape(base.note||'')}）`).join('；')}</p>`:''}<p class="tiny">本次入選作品：${escape(item?.title||'')} · ${escape(g.building.label)}</p><div class="master-card-actions"><button data-master-focus="${g.id}">聚焦人物地標</button><button data-building-dossier="${g.id}">作品資料 ↗</button><button data-select="${g.id}">前往${g.building.siteRole==='original'?'作品原址':'建築實址'} ↗</button></div></div></article>`;}
function showMasterFor(id){const cluster=[...(world?.globe?.masterClusters?.values()||[])].find(c=>c.ids.includes(Number(id)));if(cluster)showMasterCluster(cluster.key);else{const g=geography(Number(id));if(g)showMasterCluster({key:String(id),ids:[g.id],label:g.practiceBase.label,hasSelectedWork:false,coLocatedBuildingIds:[]});}}
function showMasterCluster(key){const cluster=typeof key==='object'?key:world?.globe?.masterClusters?.get(key);if(!cluster)return;const people=cluster.ids.map(id=>geography(Number(id))).filter(Boolean),localWorks=(cluster.coLocatedBuildingIds||[]).filter(id=>catalog.some(i=>i.id===Number(id)));showModal('MASTER LANDMARK / 歷史執業地標',`<h2 id="modal-title">${escape(cluster.label||people[0]?.practiceBase.label)}</h2><p>${people.length>1?`同城地標收錄 ${people.length} 組建築師，人物卡分別列出，沒有把建築島搬到這裡。`:'這是一處獨立的人物地標，建築島仍在作品的實際地點。'}</p><p class="tiny">人物依有來源的代表性歷史執業地定位，不表示國籍、出生地、現居地或完整生涯路徑。人物插畫不是史實肖像；照片另列作者、授權與來源。</p>${!cluster.hasSelectedWork?'<div class="cluster-explainer">此歷史據點附近沒有這 25 件入選作品的建築島，仍保留人物地標。附近採約 35 公里的顯示判準；這不表示當地沒有其他重要作品。</div>':localWorks.length?`<div class="cluster-explainer"><strong>此歷史據點附近的入選作品</strong><div class="island-index">${buildingIndexMarkup(localWorks)}</div><p class="tiny">附近採約 35 公里的顯示判準，不表示共用地址或同一建築。</p></div>`:''}<div class="master-card-list">${people.map(masterCardMarkup).join('')}</div>`);bindBuildingChoices();for(const button of $('modal-content').querySelectorAll('[data-master-focus]'))button.onclick=()=>{closeModal();if(current)backMap();enableLandmarkLayer('master');world?.focusMaster?.(Number(button.dataset.masterFocus));};for(const button of $('modal-content').querySelectorAll('[data-building-dossier]'))button.onclick=()=>showGeography(Number(button.dataset.buildingDossier));for(const image of $('modal-content').querySelectorAll('.master-visual.portrait img'))image.addEventListener('error',()=>{const g=people.find(person=>person.portrait?.path===image.getAttribute('src'));if(g)image.closest('figure').outerHTML=figureIllustration(g);},{once:true});}
function showBuildingCluster(tileId){const clusters=world?.globe?.buildingClusters,ids=clusters?.get(tileId)||clusters?.get(Number(tileId))||clusters?.get(String(tileId));if(!ids?.length)return;showModal('BUILDING CLUSTER / 同格作品',`<h2 id="modal-title">一格底圖，${ids.length} 件不同作品。</h2><p>這些建築共用最近的地球格網。格網不是地址：每件作品的定位點都固定在自己的場址座標，沒有為了排版而搬移。</p><p>選擇下方作品會切換此格可見的 Q 版縮景，並聚焦該建築。作品資料與原有獨立導覽仍各自保留。</p><div class="island-index">${buildingIndexMarkup(ids)}</div>`);bindBuildingChoices();}
function showGeographicAssociation(value){const id=typeof value==='object'?value.architectId:Number(String(value).replace(/^geography-/,'')),g=geography(id),item=catalog.find(i=>i.id===id);if(!g||!item)return;if(g.practiceBase.countryCode===g.building.countryCode){showGeography(id);return;}showModal('GEOGRAPHIC ASSOCIATION / 跨國地理關聯',`<div class="connection-tags"><span class="edge-type geography"><i class="legend-line geography"></i>跨國地理關聯 · 非歷史關係線</span></div><h2 id="modal-title">${escape(g.architect)}，與這件作品。</h2><div class="geography-endpoints"><div><span>歷史執業地標</span><strong>${escape(g.practiceBase.label)}</strong></div><i aria-hidden="true">↔</i><div><span>${buildingSiteLabel(g)}</span><strong>${escape(g.building.label)}</strong><small>${escape(item.title)}</small></div></div><p>青色線說明本次選用的歷史執業基地與入選作品位於不同國家／地區。它不代表國籍、出生地、現居地，也不表示任何人的移居、實際旅行、師承或任職關係。</p><p class="tiny">這類線與原有 4 條史料關係、5 條策展理念對讀分開計算，可在「地理圖層」獨立開關。沒有青色線，也不表示建築與工作室位於同一城市。</p><h3>作品所在地依據</h3>${sourceLinks(g.building.sources)}<h3>歷史執業基地依據</h3>${sourceLinks(g.practiceBase.sources)}<div class="modal-actions"><button id="association-master">查看人物卡</button><button id="association-building">作品定位資料</button><button id="association-focus" class="primary">聚焦${g.building.siteRole==='original'?'作品原址':'建築實址'}</button></div>`);$('association-master').onclick=()=>showMasterFor(id);$('association-building').onclick=()=>showGeography(id);$('association-focus').onclick=()=>{closeModal();if(current)backMap();focusBuilding(id);};}
function showAtlas(){showModal('HEX EARTH / 讀圖方式',`<h2 id="modal-title">建築在實址，人物在歷史據點。</h2><p>這顆地球的 25 座建築島依作品實際場址定位。建築師另設有來源的歷史執業地標，二者不是同一層，也不以國籍、出生地或現居地互相替代。</p>${regionalCountMarkup()}<div class="concept-card"><h3>格網是底圖，不是搬移位置的理由</h3><p>地球以六角格為主，並以 12 個五角格閉合球面。海岸與格網經過風格化；建築定位點固定在作品座標，不移至格心。同格作品用清單切換縮景，人物共用城市則列出各自卡片。</p></div><h3>歷史原址與已核實現址</h3><p>已遷移或臨時作品明確標示歷史原址，不暗示今日仍在當地。可核實的現址以次要標記呈現、另列來源，不增加典藏件數；「已核實現址」圖層可單獨開關。</p><div class="edge-key geography-key"><div><i class="legend-line geography"></i><strong>青色線：跨國地理關聯</strong><small>連接歷史執業地標與該人物的入選作品，不代表師承、任職、旅行或遷居。</small></div></div><h3>關係史料與交通示意，分開閱讀</h3><p>原有 4 條史料關係與 5 條理念對讀保持獨立。道路、航線、飛行只是一種地理呈現，不是實際歷史行程，也不能跨島行走。</p><p>4 個「未收錄區域」標記只表示這 25 件作品的主定位未涵蓋該處，不表示當地沒有建築師或重要作品。</p><div class="atlas-directory">${atlas.architects.map(g=>`<button data-geo="${g.id}"><b>${String(g.id).padStart(2,'0')}</b><span>${escape(catalog.find(i=>i.id===g.id)?.title||g.architect)}<small>${buildingSiteLabel(g)}：${escape(g.building.label)}<br>人物歷史執業：${escape(g.practiceBase.label)}</small></span></button>`).join('')}</div><p class="tiny">原 25 個獨立導覽網站保持不變。本遊戲開放 25 座探索島、75 個觀察任務；來源分別列在作品與人物資料卡。</p>`);for(const button of $('modal-content').querySelectorAll('[data-geo]'))button.onclick=()=>showGeography(Number(button.dataset.geo));}
function showEmpty(id){const e=EMPTY_ISLANDS.find(e=>e.id===id);if(!e)return;showModal('BEYOND THIS SELECTION / 本次未收錄區域',`<h2 id="modal-title">${escape(e.name.replace('無人島','未收錄區域'))}</h2><p>這裡沒有本次 25 件作品的主定位。這是選集範圍，不代表這個地區沒有重要建築、建築師或豐富文化。</p><p>此區域標記沒有 NPC 或任務，也不占用 25 件典藏名額。人物歷史執業地標與作品位置分開閱讀。</p><button id="empty-close" class="primary">繼續探索</button>`);$('empty-close').onclick=closeModal;}
const TRANSPORT_TYPES={local:{icon:'◎',label:'同城關係'},road:{icon:'≋',label:'道路'},ship:{icon:'⚓',label:'航線'},flight:{icon:'✈',label:'飛行'}};
function routeMarkup(edge){const info=world?.routeInfo?.(edge),type=TRANSPORT_TYPES[info?.mode];return type?`<span class="transport-chip ${info.mode}" title="風格化交通示意，非歷史行程"><i aria-hidden="true">${type.icon}</i> ${escape(info.label||type.label)}</span>`:'';}
function showNetwork(id=null){const edges=id?relationships.filter(e=>e.from===id||e.to===id):relationships;showModal('CONNECTION ATLAS / 連線圖鑑',`<h2 id="modal-title">${id?'建築師的思想連線':'讀關係，也讀地理。'}</h2><p>4 條有史料的關係線，與 5 條策展理念對讀分開呈現，端點是人物的歷史執業地標，不是代表作場址。授業、共事、理念是關係分類；同城、道路、航線、飛行是地理呈現，兩者不能互相推論。</p><div class="edge-key">${Object.entries(EDGE_TYPES).map(([key,t])=>`<div><i class="legend-line ${key}"></i><strong>${t.label}</strong><small>${t.description}</small></div>`).join('')}</div><div class="transport-key"><span><i aria-hidden="true">◎</i> 同城關係</span><span><i aria-hidden="true">≋</i> 鄰近陸地 · 道路</span><span><i aria-hidden="true">⚓</i> 跨水域 · 航線</span><span><i aria-hidden="true">✈</i> 遠距離 · 飛行</span></div><p class="tiny">交通是風格化的地理教學示意，不是實際歷史行程、可步行路線或旅行模擬。</p>${edges.length?`<div class="connection-list">${edges.map(e=>`<button data-connection="${e.id}"><span class="connection-tags"><span class="edge-type ${e.type}">${EDGE_TYPES[e.type].label}</span>${routeMarkup(e)}</span><strong>${escape(e.shortLabel||e.label)}</strong><small>${escape(e.summary||e.explanation)}</small><span class="read-source">閱讀依據 ↗</span></button>`).join('')}</div>`:'<p>目前尚未為這座島選入連線。沒有畫線，不代表歷史上不存在關聯；為了可讀性，本圖只保留少量經核對的案例。</p>'}<p class="tiny">這不是完整的建築史譜系。未繪出的關係並非否定其存在；理念相近也不等於師承或直接影響。青色跨國地理線另屬地理圖層，不算入以上 9 條關係。</p>`);for(const b of $('modal-content').querySelectorAll('[data-connection]'))b.onclick=()=>showConnection(b.dataset.connection);}
function showConnection(id){const e=relationships.find(e=>e.id===id);if(!e)return;const a=catalog.find(i=>i.id===e.from),b=catalog.find(i=>i.id===e.to),t=EDGE_TYPES[e.type];showModal('IDEAS IN CONNECTION / 思想連線',`<div class="connection-tags"><span class="edge-type ${e.type}">${t.label}</span>${routeMarkup(e)}</div><h2 id="modal-title">${escape(e.shortLabel||e.label)}</h2><p>${escape(e.explanation||e.summary)}</p>${e.caveat?`<div class="explanation">${escape(e.caveat)}</div>`:''}<p class="tiny">${e.type==='thematic'?'此線為本圖策展對讀，並不主張兩人有直接授業、任職或已證實的影響關係。':'方向只表示這段授業／任職經歷，不代表整體創作高低，也不把事務所工作等同完整師承。'}</p><h3>${e.type==='thematic'?'作品與理念參考':'關係史料來源'}</h3>${sourceLinks(e.sources)}<div class="modal-actions"><button data-endpoint="${a.id}">人物地標 · ${escape(a.architect)} ↗</button><button data-endpoint="${b.id}">人物地標 · ${escape(b.architect)} ↗</button></div><div class="connection-work-actions"><button data-select="${a.id}">建築實址 · ${escape(a.title)} ↗</button><button data-select="${b.id}">建築實址 · ${escape(b.title)} ↗</button></div><p class="tiny">這條線連接人物的歷史執業地標，並非代表作場址。交通樣式只依地理位置示意，非兩人的實際歷史行程；同城關係不表示共用地址。連線不可步行，也不是旅行模擬。</p><button id="back-network" class="geo-details">← 返回連線圖鑑</button>`);for(const button of $('modal-content').querySelectorAll('[data-endpoint]'))button.onclick=()=>{closeModal();if(current)backMap();enableLandmarkLayer('master');world?.focusMaster?.(Number(button.dataset.endpoint));};bindBuildingChoices();$('back-network').onclick=()=>showNetwork();}
function bind(){updateRegionalCounts();for(const b of document.querySelectorAll('[data-landmark-layer]'))b.onclick=()=>{const on=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(on));world.setLandmarkLayer?.(b.dataset.landmarkLayer,on);};for(const b of document.querySelectorAll('[data-edge-filter]'))b.onclick=()=>{const on=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(on));world.setNetworkFilter(b.dataset.edgeFilter,on);};$('network-scope').onclick=()=>{const b=$('network-scope'),on=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(on));b.textContent=on?'顯示全部連線':'只看選島';world.setNetworkScope(on?'selected':'all');};$('open-atlas').onclick=showAtlas;$('open-network').onclick=()=>showNetwork(); for(const button of document.querySelectorAll('[data-map-action]')){button.onclick=()=>world.mapAction(button.dataset.mapAction);button.disabled=false;}$('rendering-note').hidden=Boolean(world.gpu);if(innerWidth<=700)$('map-gesture-hint').textContent='單指轉地球 · 雙指縮放 · 點建築選擇'; $('home').onclick=()=>{if(current)backMap();else {selectIsland(4);world.mapAction('reset');}};$('back-map').onclick=backMap;$('help').onclick=()=>showTutorial(Boolean(current));$('passport').onclick=showPassport;$('close-modal').onclick=closeModal;$('modal').addEventListener('cancel',e=>{e.preventDefault();closeModal();});$('modal').addEventListener('click',e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});$('interact-btn').onclick=interact;$('retry-model').onclick=()=>current&&enterIsland(current.id);$('loading-map').onclick=backMap;$('rotate-left').onclick=()=>{world.rotate(-.3);world.focusControls();};$('rotate-right').onclick=()=>{world.rotate(.3);world.focusControls();};$('zoom-in').onclick=()=>{world.setZoom(-5);world.focusControls();};$('zoom-out').onclick=()=>{world.setZoom(5);world.focusControls();};$('photo-leave').onclick=()=>world.leaveObservation();$('photo-free').onclick=()=>{world.manualCamera();world.updateCamera();world.focusControls();};$('reset-camera').onclick=()=>{world.resetCamera();world.focusControls();toast('已返回俯視鏡頭，探索進度不變。');};$('time-of-day').value=progress.settings.timeOfDay;$('time-of-day').onchange=async()=>{const mode=$('time-of-day').value;const ok=await world.setTimeOfDay?.(mode);if(ok!==false){progress.settings.timeOfDay=mode;save();}else $('time-of-day').value=world.timeOfDay||progress.settings.timeOfDay;};$('lights-enabled').onchange=()=>world.setLamps?.($('lights-enabled').checked);$('quality').value=progress.settings.quality;$('quality').onchange=async()=>{const value=$('quality').value;progress.settings.quality=value;save();const ok=await world.setQuality(value);if($('quality').value!==value)return;toast(ok===false?'畫質設定已保留，部分材質更新未完成；可重選重試。':value==='low'?'省電畫質：材質最長邊 512 像素，降低像素密度並關閉陰影。':'畫質已更新，探索位置與視角不變；手機自動模式使用省電材質。');};$('objectives-toggle').onclick=()=>{const hidden=!$('objectives').hidden;$('objectives').hidden=hidden;$('objectives-toggle').setAttribute('aria-expanded',String(!hidden));};for(const b of document.querySelectorAll('[data-move]')){b.addEventListener('pointerdown',e=>{if(world.mode!=='island'||world.paused)return;e.preventDefault();world.focusControls();world.beginPad(b.dataset.move,b,e.pointerId);});const release=e=>world.releasePad(e.pointerId);for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,release);} }
async function init(){try{const results=await Promise.all([fetch('./catalog.json'),fetch('./quests.json'),fetch('./atlas.json'),fetch('./relationships.json')]);if(results.some(r=>!r.ok))throw Error('Game content unavailable');[catalog,content,atlas,relationships]=await Promise.all(results.map(r=>r.json()));const {World}=await import('./engine.js');world=new World(catalog,{select:selectIsland,toast,status:s=>$('renderer-status').textContent=s,connection:showConnection,master:showMasterCluster,cluster:showBuildingCluster,geography:showGeographicAssociation,currentSite:showGeography,empty:showEmpty,near:nearChanged,photo:photoChanged,interact,contextLost:()=>{world.setPaused(true);showModal('DISPLAY INTERRUPTED / 顯示暫停',`<h2 id="modal-title">3D 顯示暫時中斷</h2><p>裝置可能暫時沒有足夠的繪圖資源。已完成的任務仍保留；請重新載入後選擇「省電」畫質。</p><button id="reload-game" class="primary">重新載入遊戲</button>`);$('reload-game').onclick=()=>location.reload();}},atlas,relationships);bind();world.setQuality(progress.settings.quality);world.showMap();selectIsland(4);updateCounter();if(!storageOK)$('save-status').textContent='瀏覽器儲存不可用';window.addEventListener('pagehide',()=>{world.keys.clear();});window.addEventListener('storage',event=>{if(event.key!==SAVE_KEY)return;try{progress=sanitizeProgress(JSON.parse(event.newValue||'null'));updateCounter();if(current)renderObjectives();}catch{}});}catch(e){console.error(e);$('main').innerHTML='<div class="boot-error"><h1>地球暫時無法載入</h1><p>請檢查網路後再試一次。既有進度不會清除。</p><button class="primary" onclick="location.reload()">重新載入</button></div>';}}
init();
